      <section class="stack"><div class="section-head"><h2>Your conversations</h2><span class="meta">${f.saved.reduce((a, id) => a + (S.enquiries[id] || []).filter(e => e.from.name === f.name).length, 0) || 'none yet'}</span></div>${f.saved.flatMap(id => (S.enquiries[id] || []).filter(e => e.from.name === f.name).map(e => `<article class="card"><h4>${esc(byId(id).name)}</h4><div class="thread" style="margin-top:8px"><div class="msg mine">${esc(e.text)}</div>${e.state === 'sent' ? `<div class="msg">${esc(e.draft)}</div>` : (S.stage[id] === 'managing' || S.stage[id] === 'upgraded') ? `<p class="meta">Sent ${esc(e.at)} — ${esc(byId(id).name)} usually answers within minutes (sample).</p>` : `<p class="meta">${esc(byId(id).name)} has not claimed its page yet — Your Field has told them a family is asking. You will hear as soon as they answer.</p>`}</div></article>`)).join('') || '<div class="empty">Ask a saved provider about a trial (Saved) — the coach sees it in Conversations and answers from there.</div>'}</section>
