    if (p.trial && p.trial.available) list.push({ id: pid + '-trial', kind: 'Trial class', title: `${p.trial.free ? 'A free trial' : 'A trial'} at ${p.name}`, copy: `Hi {first name} — ${kid} could try ${p.primaryActivityType.toLowerCase()} at ${p.name} in ${p.neighborhood}${p.nextOccurrence && p.nextOccurrence.weekday ? ', ' + p.nextOccurrence.weekday + 's' : ''}. ${p.trial.free ? 'The first class is free.' : 'Trials by appointment.'} Reply or tap to pick a time.`, audience: { saved, nearby }, channels: ['E-mail', 'Push'], state: 'waiting', ai: S.ai.provider });
