  provider.campaigns = () => { const pid = S.providerPersona; const p = byId(pid); const managing = S.stage[pid] === 'managing' || S.stage[pid] === 'upgraded'; const list = campaignsFor(pid); return `<div><h1 class="page-title">Campaigns</h1><p class="sub">Built from your card — trial policy, next session, announcement, open registration. You approve; the platform sends to families by their preferences and never past the cap.</p></div>${managing ? `<section class="stack"><div class="section-head"><h2>Drafted for ${esc(p.name)}</h2><span class="meta">${list.filter(c => c.state === 'waiting').length} waiting · ${S.ai.provider ? 'AI drafts on' : 'AI drafts off'}</span></div>${list.map(c => campaignCard(c, pid)).join('')}</section>` : '<div class="empty">Campaigns unlock once you manage your page — open Today and apply.</div>'}`; };
